-- Complete private preserved sheets. No source documents or scalar value trees are stored.
CREATE TABLE preserved_sheet_revision (revision TEXT PRIMARY KEY, ordinal INTEGER NOT NULL UNIQUE, ledger_sha256 TEXT NOT NULL, document_sha256 TEXT NOT NULL, people_sha256 TEXT NOT NULL, serialized_sha256 TEXT NOT NULL, numeric_sha256 TEXT NOT NULL, numeric_count INTEGER NOT NULL, person_count INTEGER NOT NULL CHECK(person_count=1022), rules_version TEXT NOT NULL, resolution TEXT NOT NULL, numeric_adoption INTEGER NOT NULL CHECK(numeric_adoption=0), legacy_values TEXT NOT NULL, original_ratings TEXT CHECK(original_ratings IS NULL), actor TEXT NOT NULL CHECK(length(trim(actor))>0), reason TEXT NOT NULL CHECK(length(trim(reason))>0)) STRICT;
CREATE TABLE preserved_sheet_source (source_path TEXT PRIMARY KEY, sha256 TEXT NOT NULL) STRICT;
CREATE TABLE preserved_sheet_domain_count (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), domain TEXT NOT NULL, row_count INTEGER NOT NULL, PRIMARY KEY(revision,domain)) STRICT;
CREATE TABLE preserved_sheet_person (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "id" TEXT, "name" TEXT, "url" TEXT, "state" TEXT, "method" TEXT, "band" TEXT, "baseline" INTEGER, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_role (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "display" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_attributes (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_attribute (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "value" REAL, "cp" REAL, "rule" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_trait (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "kind" TEXT, "rule" TEXT, "level" REAL, "people" REAL, "frequency" REAL, "cp" REAL, "page" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_skill (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "ko" TEXT, "attr" TEXT, "diff" TEXT, "tier" TEXT, "cp" REAL, "level" REAL, "difficulty" TEXT, "effect" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_language (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "level" TEXT, "cp" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_secondary (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "HP" REAL, "Will" REAL, "Per" REAL, "FP" REAL, "BasicSpeed" REAL, "BasicMove" REAL, "BasicLift" REAL, "Dodge" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_cp (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "attributes" REAL, "advantages" REAL, "disadvantages" REAL, "skills" REAL, "spent" REAL, "unspent" REAL, "total" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_unit (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "type" TEXT, "size" REAL, "quality" TEXT, "note" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_faction_scale (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "state" TEXT, "tier" TEXT, "factor" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_force (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "type" TEXT, "size" REAL, "current_location" TEXT, "note" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_camp (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "type" TEXT, "description" TEXT, "pack_up_time" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_territory (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "fief_name" TEXT, "type" TEXT, "station" TEXT, "state" TEXT, "note" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_settlement (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "type" TEXT, "description" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_advantage (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "cp" REAL, "effect" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_disadvantage (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "name" TEXT, "cp" REAL, "effect" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_reaction (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "ordinaryObservers" REAL, "observersAttractedToHerSex" REAL, "application" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_boundary (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "text" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_composition (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "text" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_facility (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "text" TEXT, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_role_evidence (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "path" TEXT, "pointer" TEXT, "quote" TEXT, "note" TEXT, "line" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_attribute_evidence (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "path" TEXT, "pointer" TEXT, "quote" TEXT, "note" TEXT, "line" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_trait_evidence (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "path" TEXT, "pointer" TEXT, "quote" TEXT, "note" TEXT, "line" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_skill_evidence (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "path" TEXT, "pointer" TEXT, "quote" TEXT, "note" TEXT, "line" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
CREATE TABLE preserved_sheet_language_evidence (revision TEXT NOT NULL REFERENCES preserved_sheet_revision(revision), person_id TEXT NOT NULL, slot TEXT NOT NULL, key_order TEXT NOT NULL, "path" TEXT, "pointer" TEXT, "quote" TEXT, "note" TEXT, "line" REAL, PRIMARY KEY(revision,person_id,slot)) STRICT;
